/// <reference types="../../../types/react-table-config" />

import React from 'react';

import { TableRow } from '../../../types/shared-table-types.js';

export interface TableCellActionsProps {
  /**
   * The accessor/id of the column the user actions belong to. If this property is not set,
   * the configuration is used as a fallback for all columns where no user actions are defined explicitly.
   */
  column?: string;

  children: (props: {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    column: any;
    // eslint-disable-next-line @typescript-eslint/ban-types
    row: TableRow<{}>;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    cell: { value: any };
  }) => React.ReactNode;
}

/**
 * Configuration component used for defining user actions for table cells.
 * This component can only be used as a child element of `<DataTable.UserActions>`.
 */
export const CellActions = ({ children }: TableCellActionsProps) => (
  <>{children}</> // eslint-disable-line react/jsx-no-useless-fragment
);

CellActions['displayName'] = 'DataTable.CellActions';
